def minPath(grid, k):
    n = len(grid)
    def dfs(row, col, visited, path):
        if len(path) == k:
            return path
        if row < 0 or row >= n or col < 0 or col >= n or (row, col) in visited:
            return None
        visited.add((row, col))
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            new_row = row + dr
            new_col = col + dc
            new_path = path + [grid[row][col]]
            result = dfs(new_row, new_col, visited.copy(), new_path)
            if result:
                return result
        visited.remove((row, col))
        return None

    min_path = None
    for row in range(n):
        for col in range(n):
            visited = set()
            result = dfs(row, col, visited, [])
            if result and (min_path is None or result < min_path):
                min_path = result 
    return min_path



