from collections import deque

def minPath(grid, k):
    n = len(grid)
    visited = set()
    queue = deque([(0, 0, [grid[0][0]], 1)])  

    while queue:
        i, j, path, len_path = queue.popleft()
        if len_path == k:
            return path

        if (i, j) in visited:
            continue
        visited.add((i, j))

        dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for di, dj in dirs:
            new_i, new_j = i + di, j + dj
            if 0 <= new_i < n and 0 <= new_j < n:
                queue.append((new_i, new_j, path + [grid[new_i][new_j]], len_path + 1))            

