from collections import deque

def minPath(grid, k):
    n = len(grid)
    queue = deque([(0, 0, [grid[0][0]], 1)])
    visited = set([(0, 0)])
    while queue:
        i, j, path, len_path = queue.popleft()
        if len_path == k:
            return path
        for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
            if 0 <= x < n and 0 <= y < n and (x, y) not in visited:
                visited.add((x, y))
                queue.append((x, y, path + [grid[x][y]], len_path + 1))
