def largest_prime_factor(n: int):
    i = 2
    largest_factor = 1
    while i * i <= n:
      if n % i == 0:
        largest_factor = i 
        n //= i
      else:
        i += 1
    if n > 1:
      largest_factor = n
    return largest_factor   
```

