    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    counts = {}
    for word in test.split():
      if word in counts:
        counts[word]+=1
      else:
        counts[word]=1
    return {letter: count for letter, count in counts.items() if count == max(counts.values())} 
