def max_fill(grid, capacity):
    import math
    rows = len(grid)
    cols = len(grid[0])
    bucket_full = 0
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                bucket_full += 1
        if bucket_full >= capacity:
            count += 1
            bucket_full = 0
    if bucket_full > 0:
        count += 1
    return count 
