    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    result = []
    for i in s:
        if i.isalpha():
            result.append(i.swapcase())
        else:
            result.append(i)
    if not any(c.isalpha() for c in s):
        result.reverse()
    return ''.join(result) 
