def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = ''
    for letter in s:
      if letter in alphabet:
        index = alphabet.find(letter)
        new_index = (index + 4) % 26
        result += alphabet[new_index]
      else:
        result += letter
    return result    
