from collections import deque

def minPath(grid, k):
    n = len(grid)
    visited = set()
    queue = deque([(grid[0][0], [grid[0][0]], 1)])
    while queue:
        cell, path, length = queue.popleft()
        if length == k:
            return path
        if cell in visited:
            continue
        visited.add(cell)
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = cell[0] + dx, cell[1] + dy
            if 0 <= nx < n and 0 <= ny < n:
                queue.append(( (nx, ny), path + [grid[nx][ny]], length + 1))
