from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    results = []
    for group in paren_string.split():
        max_nest = 0
        nest = 0
        for char in group:
            if char == '(':
                nest += 1
                max_nest = max(max_nest, nest)
            elif char == ')':
                nest -= 1
        results.append(max_nest)
    return results
