def pluck(arr):
    if not arr:
        return []
    min_even = float('inf')
    index = -1
    for i, node in enumerate(arr):
        if node % 2 == 0 and node < min_even:
            min_even = node
            index = i
    return [min_even, index] if index != -1 else [] 
