import queue

def minPath(grid, k):
    N = len(grid)
    visited = set()
    queue = [(0,0,[],0)]
    while queue:
        i,j,path,len_path = queue.pop(0)
        if len_path == k:
            return path
        if (i,j) not in visited:
            visited.add((i,j))
            directions = [(0,1), (1,0), (0,-1), (-1,0)]
            for r,c in directions:
                new_i, new_j = i + r, j + c
                if 0 <= new_i < N and 0 <= new_j < N:
                    queue.append((new_i, new_j, path + [grid[new_i][new_j]],len_path + 1))



