from collections import deque

def minPath(grid, k):
    n = len(grid)
    visited = set()
    queue = deque([(0, 0, 0, [])])
    while queue:
        row, col, length, path = queue.popleft()
        if length == k:
            return path

        visited.add((row, col))
        if row + 1 < n and (row + 1, col) not in visited:
            queue.append((row + 1, col, length + 1, path + [grid[row + 1][col]]))
        if row - 1 >= 0 and (row - 1, col) not in visited:
            queue.append((row - 1, col, length + 1, path + [grid[row - 1][col]]))
        if col + 1 < n and (row, col + 1) not in visited:
            queue.append((row, col + 1, length + 1, path + [grid[row][col + 1]]))
        if col - 1 >= 0 and (row, col - 1) not in visited:
            queue.append((row, col - 1, length + 1, path + [grid[row][col - 1]]))   
