from queue import Queue

def minPath(grid, k):
    n = len(grid)
    visited = set()
    queue = Queue()
    queue.put((0, 0, [grid[0][0]], 1))
    while not queue.empty():
        i, j, path, length = queue.get()
        if length == k:
            return path
        if (i, j) in visited:
            continue
        visited.add((i, j))
        for di, dj in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                queue.put((ni, nj, path + [grid[ni][nj]], length + 1))              
