def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    encrypted_text = ''
    for char in s:
        if char in alphabet:
            index = alphabet.find(char)
            shifted_index = (index + (2 * 2)) % 26
            encrypted_text += alphabet[shifted_index]
        else:
            encrypted_text += char
    return encrypted_text  
