    visited = set()
    queue = deque([(grid[0][0], [grid[0][0]], 1)])
    while queue:
        val, path, len_path = queue.popleft()
        if len_path == k:
            return path
        if (val, path) in visited:
            continue
        visited.add((val, path))
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = val // n, val % n + dx
            if 0 <= nx < n and 0 <= ny < n:
                queue.append((nx * n + ny, path + [nx * n + ny], len_path + 1))



