from collections import deque

def minPath(grid, k):
    n = len(grid)
    visited = set()
    queue = deque([(grid[0][0], 1, [grid[0][0]])])
    while queue:
      curr, steps, path = queue.popleft()
      if steps == k:
        return path
      for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
        nx, ny = curr[0] + dx, curr[1] + dy
        if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
          visited.add((nx, ny))
          queue.append(( (nx, ny), steps + 1, path + [grid[nx][ny]]))
