    valid_date('15-01-2012') => False

    valid_date('04-0-2040') => False

    valid_date('06-04-2020') => True

    valid_date('06/04/2020') => False
    """
    if not date:
        return False
    try:
        mm, dd, yyyy = map(int, date.split('-'))
    except:
        return False
    if not (1 <= mm <= 12 and 1 <= dd <= 31):
        if mm == 2:
            if not (1 <= dd <= 29):
                return False  
        elif mm in [4, 6, 9, 11]:
