def prime_fib(n: int):
    a = 0
    b = 1
    count = 0
    while count < n:
        if is_prime(a):
            count += 1
        a, b = b, a + b
    return a


def is_prime(n: int):
  if n <= 1:
    return False
  for base in range(2, int(n ** 0.5) + 1):
    if n % base == 0:
      return False
  return True 
```

